using System;using System.IO;using System.Linq;using System.Collections.Generic;using FocusGrowth;
namespace FocusGrowthMigration {
public static class MigrationTests {
 sealed class Api:System.Net.Http.HttpMessageHandler {
  public Snapshot Current=Remote();public int Puts;public bool Conflict,Offline;public List<string> Destinations=new List<string>();
  protected override System.Threading.Tasks.Task<System.Net.Http.HttpResponseMessage> SendAsync(System.Net.Http.HttpRequestMessage req,System.Threading.CancellationToken cancel){Destinations.Add(req.RequestUri.AbsoluteUri);object data;int code=200;if(req.Method.Method=="PUT"){Puts++;if(Offline)throw new System.Net.Http.HttpRequestException();var body=J.Obj(J.Parse(req.Content.ReadAsStringAsync().GetAwaiter().GetResult()));if(Conflict||J.Str(body["sha"])!=Current.Sha){code=409;data=new{message="synthetic conflict"};}else{Current=new Snapshot{Sha=new string('e',40),State=J.Obj(J.Parse(System.Text.Encoding.UTF8.GetString(Convert.FromBase64String((string)body["content"]))))};data=new{commit=new{sha=new string('f',40)}};}}else if(req.RequestUri.AbsolutePath.EndsWith("sync/state.json"))data=new{type="file",encoding="base64",sha=Current.Sha,content=Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(J.Dump(Current.State)))};else data=new{full_name="tang0709/focus-growth-data",@private=true};return System.Threading.Tasks.Task.FromResult(new System.Net.Http.HttpResponseMessage((System.Net.HttpStatusCode)code){Content=new System.Net.Http.StringContent(J.Dump(data))});}
 }
 sealed class Once:IOnce {public int Calls;public void Consume(Approval a){if(Calls++>0)throw new Fault("spent");}}
 static Dictionary<string,object> Db(){var db=J.Copy(PreparationTests.Full());db["plans"]=new[]{new{id="plan-test",taskId="t-test",date="2026-11-21",start=540,duration=30}};return J.Copy(db);}
 static Approval A(Dictionary<string,object> db){return new Approval{ConsentId="synthetic-consent",Preview=new string('a',64),Backup=new string('b',64),Full=LocalJson.Digest(db),Local=LocalJson.Digest(PreparationModel.Project(db)),Remote=new string('c',40),Counts=new[]{1,1,1}};}
 static Snapshot Remote(){return new Snapshot{Sha=new string('c',40),State=Schema.Empty()};}
 static void Denied(Action f){try{f();}catch(Fault){return;}throw new Exception();}
 public static int Run(string folder){var rows=new List<object>();Action<string,Action> test=(name,f)=>{try{f();rows.Add(new{name,pass=true});}catch{rows.Add(new{name,pass=false});}};
 test("valid_initialization_whitelist_revision_and_stable_ids",()=>{var db=Db();var a=A(db);var p=Gate.Payload(a,db,db,Remote(),a.Preview,a.Backup);Schema.Require((int)p["revision"]==1&&(bool)p["initialized"]&&J.Arr(p["operationIds"]).Contains(a.OperationId),"bad");Schema.Require(J.Str(J.Obj(J.Arr(p["tasks"])[0])["id"])=="t-test","bad");Schema.Require(!J.Dump(p).Contains("LOCAL_PRIVATE_TEST_CANARY")&&!p.ContainsKey("history")&&!p.ContainsKey("activity"),"leak");});
 foreach(string field in new[]{"preview","backup","local","full","remote","counts"}){string f=field;test("reject_changed_approval_"+f,()=>{var db=Db();var a=A(db);switch(f){case "preview":a.Preview=new string('d',64);break;case "backup":a.Backup=new string('d',64);break;case "local":a.Local=new string('d',64);break;case "full":a.Full=new string('d',64);break;case "remote":a.Remote=new string('d',40);break;default:a.Counts=new[]{3,25,12};break;}Denied(()=>Gate.Payload(a,db,db,Remote(),new string('a',64),new string('b',64)));});}
 test("reject_changed_local_only_fields",()=>{var db=Db();var changed=J.Copy(db);changed["history"]=new[]{new{type="real_change"}};var a=A(db);Denied(()=>Gate.Payload(a,db,changed,Remote(),a.Preview,a.Backup));});
 test("reject_reinitialization_even_with_same_counts",()=>{var db=Db();var a=A(db);var r=Remote();r.State["initialized"]=true;Denied(()=>Gate.Payload(a,db,db,r,a.Preview,a.Backup));});
 test("reject_nonempty_remote",()=>{var db=Db();var a=A(db);var r=Remote();r.State=Tests.Fixture();Denied(()=>Gate.Payload(a,db,db,r,a.Preview,a.Backup));});
 test("reject_changed_remote_revision",()=>{var db=Db();var a=A(db);var r=Remote();r.State["revision"]=1;Denied(()=>Gate.Payload(a,db,db,r,a.Preview,a.Backup));});
 test("reject_unknown_remote_schema",()=>{var db=Db();var a=A(db);var r=Remote();r.State["schemaVersion"]=2;Denied(()=>Gate.Payload(a,db,db,r,a.Preview,a.Backup));});
 test("reject_demo_source",()=>{var db=Db();db["demo"]=true;var a=A(db);Denied(()=>Gate.Payload(a,db,db,Remote(),a.Preview,a.Backup));});
 test("unknown_actual_is_preserved",()=>{var db=Db();var a=A(db);Schema.Require(J.Get(J.Obj(J.Arr(Gate.Payload(a,db,db,Remote(),a.Preview,a.Backup)["tasks"])[0]),"actual")==null,"actual_invented");});
 test("one_approval_one_commit_only",()=>{var db=Db();var a=A(db);var once=new Once();int writes=0;Gate.Execute(a,db,()=>db,Remote(),a.Preview,a.Backup,once,(p,s)=>writes++);Denied(()=>Gate.Execute(a,db,()=>db,Remote(),a.Preview,a.Backup,once,(p,s)=>writes++));Schema.Require(writes==1,"replayed");});
 test("local_change_after_consumption_stops_write",()=>{var db=Db();var a=A(db);int reads=0,writes=0;Func<Dictionary<string,object>> current=()=>{if(++reads==2){var d=J.Copy(db);d["notes"]=new object[0];return d;}return db;};Denied(()=>Gate.Execute(a,db,current,Remote(),a.Preview,a.Backup,new Once(),(p,s)=>writes++));Schema.Require(writes==0,"wrote");});
 test("network_failure_is_not_automatically_retried",()=>{var db=Db();var a=A(db);var once=new Once();int writes=0;Denied(()=>Gate.Execute(a,db,()=>db,Remote(),a.Preview,a.Backup,once,(p,s)=>{writes++;throw new Fault("network");}));Denied(()=>Gate.Execute(a,db,()=>db,Remote(),a.Preview,a.Backup,once,(p,s)=>writes++));Schema.Require(writes==1,"retried");});
 test("legacy_production_lock_remains",()=>Denied(()=>Cloud.AssertWritePath("sync/state.json")));
 test("durable_consumption_survives_new_instance",()=>{string work=Path.Combine(Path.GetFullPath(Path.Combine(folder,"..","..")),"work","first-migration","synthetic-once-"+Guid.NewGuid().ToString("N"));var a=A(Db());new OnceDisk(work).Consume(a);Denied(()=>new OnceDisk(work).Consume(a));});
 test("http_pipeline_synthetic_put_and_readback_exact_fixed_destination",()=>{var db=Db();var a=A(db);var api=new Api();using(var t=new ProductionHttp(api)){t.Migrate(a,db,()=>db,a.Preview,a.Backup,new Once());}Schema.Require(api.Puts==1&&api.Destinations.All(u=>u=="https://api.github.com/repos/tang0709/focus-growth-data"||u=="https://api.github.com/repos/tang0709/focus-growth-data/contents/sync/state.json?ref=main"||u=="https://api.github.com/repos/tang0709/focus-growth-data/contents/sync/state.json"),"wrong_destination");Schema.Require((int)api.Current.State["revision"]==1,"bad_revision");});
 test("http_sha_conflict_stops_without_retry",()=>{var db=Db();var a=A(db);var api=new Api{Conflict=true};using(var t=new ProductionHttp(api))Denied(()=>t.Migrate(a,db,()=>db,a.Preview,a.Backup,new Once()));Schema.Require(api.Puts==1&&!(bool)api.Current.State["initialized"],"retried_or_changed");});
 test("http_uncertain_result_consumes_grant_and_never_retries",()=>{var db=Db();var a=A(db);var api=new Api{Offline=true};var once=new Once();using(var t=new ProductionHttp(api)){Denied(()=>t.Migrate(a,db,()=>db,a.Preview,a.Backup,once));Denied(()=>t.Migrate(a,db,()=>db,a.Preview,a.Backup,once));}Schema.Require(api.Puts==1,"retried");});
 int passed=rows.Count(x=>J.Dump(x).Contains("\"pass\":true"));File.WriteAllText(Path.Combine(folder,"migration-test-results.json"),J.Dump(new{passed,total=rows.Count,tests=rows}));return passed==rows.Count?0:1;
 }
}
}
